export function getMPMLAProfile(acNo: number): MLAProfile | undefined {
  return MP_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getMPMLAsByParty(party: string): MLAProfile[] {
  return MP_MLA_PROFILES.filter(p => p.party === party);
}

export function getMPFemaleMLAs(): MLAProfile[] {
  return MP_MLA_PROFILES.filter(p => p.gender === 'F');
}
